from pathlib import Path
import json,hashlib,copy
R=Path(__file__).resolve().parent;sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();obj=json.loads((R/'reasoning-records.json').read_text());rows=obj['records'];pins={x['head'][:12]:x for n in [1,2]for x in json.loads((R/f'source-pins-batch{n}.json').read_text())}
for short,task,question,answer in [
('7d7cadd19113','reject_optimization','A staged-kernel prefetch proposal claims it hides metadata latency without changing outputs. A later source report says register usage rose and prefill slowed. Explain the failed optimization, the correction and which performance claim is defensible.', 'Prefetching can move a memory stall while lengthening live ranges enough to lower occupancy. The later report attributes5–11 additional registers per item/kernel to retaining both current and next metadata plus an index; K-quant prefill became1.5–5% slower in the reported M5 Max cases. The correction reuses the slot whose metadata has already been consumed and derives unit transitions from step indices. It is described as restoring earlier register use and prefill speed, not a new gain beyond the prior baseline. Preserve both chronological records: the original unchanged-output claim does not establish a speedup, and the subsequent regression disqualifies the uncorrected proposal as a positive edit target. No local profiling or timing was run here.'),
('f3a511e50aa3','review_correctness','A GGUF prefill tile has two loop instantiations whose barriers are textually similar. Idle-GPU tests pass, but partial tiles fail under load. Why can this be a real data race, and how should the reported M3 slowdown affect the repair?', 'All threads in a threadgroup must encounter the same dynamically participating threadgroup barrier. Different loop instantiations selected by whether a simdgroup owns rows can yield distinct barrier sites; an idle simdgroup can then restage double-buffered weights before others consume them. Run one common staging/barrier/prefetch loop and predicate only row-owned matmul/store work. Retain partial tiles with several idle simdgroups, busy-GPU trials, untouched-tail canaries and shader validation. The source reports a Q4K slowdown on M3 despite the correctness repair, while branch-free/likely/loop-order probes did not remove it. Do not label the branch as proven cause or retain a racy implementation to preserve speed. The measurements and pass/fail counts are historical author reports, not tests executed for this dataset.')]:
 pin=pins[short];case=pin['repository']+'-'+short+'-hour-v3';p=R/'sourcepacks'/case/'commit-message.txt';body=p.read_text();ev=[{'path':str(p),'sha256':sha(p),'url':pin['url']+'/commit/'+pin['head'],'quote':body}];extra=''
 if short.startswith('7d7'):
  later=R/'evidence/splash-later-metadata-prefetch-regression.txt';text=later.read_text();ev.append({'path':str(later),'sha256':sha(later),'url':'https://github.com/incoai/splash/commit/74f0fee245fe9d7db6d0253f508bd96fcfb711d0','quote':text});extra='\nLater chronological correction:\n'+text
 row=copy.deepcopy(rows[-1]);row.update({'id':case+'-reasoning','repo':pin['url'],'commit':pin['head'],'parent':pin['parent'],'lineage':'splash-related-optimization-training','task_type':task,'source_evidence':ev,'prompt':'Interpret these historical source records; they are not tool observations from this conversation.\n\n'+body+extra+'\nReview task: '+question,'completion':answer,'outcome_class':'rejected'if short.startswith('7d7')else'correctness','licenses':[{'path':str(R/l['path']),'sha256':l['sha256']}for l in pin['licenses']]})
 rows.append(row)
(R/'reasoning-records-v2.json').write_text(json.dumps(obj,indent=2,ensure_ascii=False)+'\n');print(len(rows))
